package com.MITProjectService.bot.dao.jpaRepos;import com.MITProjectService.bot.domain.ServiceCategory;import com.MITProjectService.bot.enums.CommonEnums;import io.lettuce.core.dynamic.annotation.Param;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.JpaSpecificationExecutor;import org.springframework.data.jpa.repository.Query;import org.springframework.stereotype.Repository;import java.util.List;@Repositorypublic interface ServiceCategoryRepository extends JpaRepository<ServiceCategory,Long> , JpaSpecificationExecutor<ServiceCategory> {    @Query("select c from ServiceCategory c where c.status = :status")    List<ServiceCategory> getAllEnabled(@Param("status") int status);}